import java.util.*;
import java.io.*;

public class DivisibleByTwentyFive {
    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        String patternStr = sc.next();
        int maxNumber = 1;
        for (int i = 0; i < patternStr.length(); i++) {
            maxNumber *= 10;
        }
        int total = 0;
        for (int num = 0; num < maxNumber; num += 25) {
            if (isMatch(patternStr, num)) {
                total++;
            }
        }
        out.println(total);
        out.close();
    }

    public static boolean isMatch(String pattern, int num) {
        int lastDigit = -1;
        for (int i = pattern.length() - 1; i >= 0; i--) {
            int currentDigit = num % 10;
            char c = pattern.charAt(i);
            if (c == 'X') {
                if (lastDigit >= 0 && lastDigit != currentDigit) {
                    return false;
                }
                lastDigit = currentDigit;
            } else if (c != '_') {
                if (c - '0' != currentDigit) {
                    return false;
                }
            }
            if (pattern.length() > 1 && i == 0 && currentDigit == 0) {
                return false;
            }
            num /= 10;
        }
        return true;
    }
}
